{"query": "WITH hypo AS (
  SELECT "Gene name" AS g, TRY_CAST(nTPM AS DOUBLE) AS h FROM rna_brain_region_hpa WHERE "Brain region"='hypothalamus' AND "Gene name" IN ('ADAM29','ADGRF4','AGRP','AVP','BSX','CLC','FEZF1','FOXB2','GAL','GHRH','GHSR','GSX1','GZMB','HCRT','HDC','ISL1','KISS1','MAGEL2','MC3R','MYL2','NKX2-4','NOMO1','NPVF','NPY','NR0B1','NR5A1','OXT','PGR','POMC','PRG4','RADX','RBP4','SHISAL2A','SIX6','SOX3','TRBV7-2','VGF','ZCCHC12')
), ctx AS (
  SELECT "Gene name" AS g, TRY_CAST(nTPM AS DOUBLE) AS c FROM rna_brain_region_hpa WHERE "Brain region"='cerebral cortex' AND "Gene name" IN ('ADAM29','ADGRF4','AGRP','AVP','BSX','CLC','FEZF1','FOXB2','GAL','GHRH','GHSR','GSX1','GZMB','HCRT','HDC','ISL1','KISS1','MAGEL2','MC3R','MYL2','NKX2-4','NOMO1','NPVF','NPY','NR0B1','NR5A1','OXT','PGR','POMC','PRG4','RADX','RBP4','SHISAL2A','SIX6','SOX3','TRBV7-2','VGF','ZCCHC12')
)
SELECT hypo.g, hypo.h AS hypo_nTPM, ctx.c AS cortex_nTPM, ROUND(hypo.h / NULLIF(ctx.c,0), 2) AS ratio FROM hypo JOIN ctx ON hypo.g=ctx.g ORDER BY ratio DESC NULLS LAST"}

{"query": "WITH t AS (
  SELECT r."Gene name" AS gene, r.Tissue, TRY_CAST(r.nTPM AS DOUBLE) AS ntp, m.Organ
  FROM rna_tissue_consensus r JOIN rna_tissue_consensus_tissues m ON r.Tissue = m.Tissue
  WHERE m.Organ <> 'Brain' AND r."Gene name" IN ('ADAM29','ADGRF4','AGRP','AVP','BSX','CLC','FEZF1','FOXB2','GAL','GHRH','GHSR','GSX1','GZMB','HCRT','HDC','ISL1','KISS1','MAGEL2','MC3R','MYL2','NKX2-4','NOMO1','NPVF','NPY','NR0B1','NR5A1','OXT','PGR','POMC','PRG4','RADX','RBP4','SHISAL2A','SIX6','SOX3','TRBV7-2','VGF','ZCCHC12')
)
SELECT gene, Tissue, ntp FROM (
  SELECT gene, Tissue, ntp, ROW_NUMBER() OVER (PARTITION BY gene ORDER BY ntp DESC) AS rn
  FROM t
) WHERE rn=1 ORDER BY ntp DESC"}

{"query": "WITH cohort AS (
  SELECT Gene, "Subcellular main location" AS loc FROM proteinatlas
  WHERE Gene IN ('ADAM29','ADGRF4','AGRP','AVP','BSX','CLC','FEZF1','FOXB2','GAL','GHRH','GHSR','GSX1','GZMB','HCRT','HDC','ISL1','KISS1','MAGEL2','MC3R','MYL2','NKX2-4','NOMO1','NPVF','NPY','NR0B1','NR5A1','OXT','PGR','POMC','PRG4','RADX','RBP4','SHISAL2A','SIX6','SOX3','TRBV7-2','VGF','ZCCHC12')
)
SELECT TRIM(s) AS location, COUNT(*) AS genes FROM cohort, UNNEST(STRING_SPLIT(loc, ',')) AS s WHERE loc <> '' GROUP BY TRIM(s) ORDER BY genes DESC"}

{"query": "PIVOT (
  SELECT "Gene name" AS gene, "Brain region" AS region, ROUND(LOG10(TRY_CAST(nTPM AS DOUBLE)+1), 3) AS logn
  FROM rna_brain_region_hpa
  WHERE "Gene name" IN ('GHRH','HCRT','OXT','HDC','BSX','NR5A1','GAL','MYL2','NKX2-4','MC3R','AVP','NPVF','PRG4','GSX1','FEZF1')
)
ON region USING FIRST(logn) ORDER BY gene"}

